function validate([dominoes]) {
  if (!Array.isArray(dominoes) || dominoes.length < 1 || dominoes.length > 40000) return 'dominoes needs 1 to 40000 dominoes.';
  for (const domino of dominoes) {
    if (!Array.isArray(domino) || domino.length !== 2) return 'Each domino is a pair [a, b].';
    if (domino.some(v => !Number.isInteger(v) || v < 1 || v > 9)) return 'Each domino face is an integer from 1 to 9.';
  }
  return null;
}

