function numEquivDominoPairs(dominoes) {
  const count = new Array(100).fill(0);
  let pairs = 0;

  for (const [a, b] of dominoes) {
    const key = Math.min(a, b) * 10 + Math.max(a, b);
    pairs += count[key];
    count[key]++;
  }
  return pairs;
}

