function numEquivDominoPairs(dominoes) {
  let total = 0;
  for (let i = 0; i < dominoes.length; i++) {
    for (let j = i + 1; j < dominoes.length; j++) {
      const [a, b] = dominoes[i];
      const [c, d] = dominoes[j];
      if ((a === c && b === d) || (a === d && b === c)) total++;
    }
  }
  return total;
}

