function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  // A small range of face values makes many matches; the full range makes few.
  const top = large ? (rand() < 0.5 ? 9 : 3) : (rand() < 0.6 ? 3 : 9);
  const face = () => 1 + Math.floor(rand() * top);
  return [Array.from({ length: n }, () => [face(), face()])];
}
